predicted_sql:
SELECT SUM(s.NumTstTakr) FROM satscores s 
WHERE s.cds IN (
    SELECT f.CDSCode FROM frpm f 
    WHERE f."FRPM Count (K-12)" = (
        SELECT MAX("FRPM Count (K-12)") FROM frpm 
        WHERE "FRPM Count (K-12)" IS NOT NULL
    )
);

SELECT "School", "Street", "City", "Zip"
FROM frpm
WHERE ABS("Enrollment (K-12)" - "Enrollment (Ages 5-17)") > 30;

SELECT "School" AS school_name, "City" AS city, TRIM(CONCAT("AdmFName1", ' ', "AdmLName1")) AS administrator1, TRIM(CONCAT("AdmFName2", ' ', "AdmLName2")) AS administrator2, TRIM(CONCAT("AdmFName3", ' ', "AdmLName3")) AS administrator3
FROM schools
WHERE "Charter" = 1 AND "CharterNum" = '00D2';
